import hashlib,json,sys
from pathlib import Path
r=Path(sys.argv[1]); total=0; unexpected=[]
for sub in ["binary","source-template"]:
 p=r/sub; j=json.loads((p/"journal.json").read_text()); records=j if isinstance(j,list) else j["commands"]
 for c in records:
  for stream in ["stdout","stderr"]:
   f=p/c[stream]; actual=hashlib.sha256(f.read_bytes()).hexdigest(); assert actual==c[stream+"_sha256"],str(f)
  if c["exit_code"]!=0: unexpected.append({"sub":sub,"label":c.get("label",c.get("name")),"exit":c["exit_code"]})
 total+=len(records)
print(json.dumps({"captured_stream_hashes_valid":True,"commands_checked_before_this_capture":total,"nonzero_captures":unexpected},indent=2))
